import csv
from datetime import datetime
temp_id="108335ab-9ad0-5222-b9a5-88d998152c65"
cool_id="335c2ab2-c7e3-551f-8bdc-96b15c59e4a8"
def load(tid):
    d={}
    with open(VALUES_CSV) as f:
        for r in csv.DictReader(f):
            if r['timeseries_id']==tid:
                d[r['timestamp']]=float(r['value'])
    return d
temp=load(temp_id); cool=load(cool_id)
def hour_ok(ts):
    h=datetime.strptime(ts,'%Y-%m-%dT%H:%M:%S').hour
    return 8<=h<=18
def dev(ts):
    if ts in temp and ts in cool:
        return temp[ts]-cool[ts]
    return None
def mean(date):
    vals=[dev(ts) for ts in temp if ts.startswith(date) and hour_ok(ts) and dev(ts) is not None]
    return sum(vals)/len(vals), len(vals)
